"""Render the decoded topology of a core frame as Markdown. It decides no verdict (AD-1121)."""

from __future__ import annotations

from collections.abc import Sequence

from .core_topology import Topology

_NONE: str = "None declared."


def render(topology: Topology) -> str:
    """The Markdown guide of one topology. The same topology gives the same bytes."""
    parts = [
        "# Architecture guide",
        "",
        "Generated by `archkeel report --format markdown`. It shows declared facts, not verdicts.",
        "",
        *_status(topology),
        *_components(topology),
        *_requires(topology),
        *_layers(topology),
    ]
    return "\n".join(parts).rstrip("\n") + "\n"


def _code(text: str) -> str:
    """One code span. A backtick would end the span, so it shows as an apostrophe."""
    return "`" + text.replace("`", "'") + "`"


def _status(topology: Topology) -> list[str]:
    if topology.complete:
        return ["The core lists every component and requirement of the contract.", ""]
    lines = [
        "The core marks this topology as incomplete. Read the gaps before you rely on it.",
        "",
    ]
    lines += [f"- Gap: {gap}" for gap in topology.gaps]
    lines.append(
        f"- Listed: {len(topology.components)} of {topology.total['components']} components; "
        f"{len(topology.requires)} of {topology.total['requires']} requirements."
    )
    return [*lines, ""]


def _bullets(items: Sequence[str], *, code: bool = False) -> list[str]:
    if not items:
        return [_NONE, ""]
    rows = [f"- {_code(item) if code else item}" for item in items]
    return [*rows, ""]


def _components(topology: Topology) -> list[str]:
    lines = ["## Components", ""]
    for item in topology.components:
        lines += [f"### {item.name} ({_code(item.id)})", ""]
        status = "planned" if item.planned else "declared"
        lines.append(f"- Status: {status}")
        lines.append(f"- Layer: {item.layer or 'not set'}")
        lines.append(f"- Parent: {_code(item.parent) if item.parent else 'none'}")
        lines += ["", "Packages:", ""]
        lines += _bullets(item.packages, code=True)
        lines += ["Exact modules:", ""]
        lines += _bullets(item.exact_modules, code=True)
        lines += ["Responsibilities:", ""]
        lines += _bullets(item.responsibilities)
        lines += ["Must not:", ""]
        lines += _bullets(item.forbidden_responsibilities)
        lines += ["Public interfaces:", ""]
        lines += _bullets(item.public, code=True)
        if item.planned_public:
            lines += ["Planned public interfaces:", ""]
            lines += _bullets(item.planned_public, code=True)
    if not topology.components:
        lines += [_NONE, ""]
    return lines


def _requires(topology: Topology) -> list[str]:
    lines = ["## Requirements", ""]
    for item in topology.requires:
        via = f"; through {', '.join(item.through)}" if item.through else ""
        lines.append(
            f"- {_code(item.source)} requires {_code(item.target)}: {item.rationale} "
            f"({item.imports} observed imports{via})"
        )
    if not topology.requires:
        lines.append(_NONE)
    return [*lines, ""]


def _layers(topology: Topology) -> list[str]:
    lines = ["## Layer orders", "", "Each order runs from the inner layer to the outer layer.", ""]
    for item in topology.layers:
        order = " -> ".join(item.layers)
        lines.append(f"- {_code(item.rule)}: {order}")
    if not topology.layers:
        lines.append(_NONE)
    return [*lines, ""]
